  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "明确了 GEMM 的函数、维度、输入参数、空维度行为，以及逻辑、数学和执行三层状态；动机与流水覆盖条件相连。",
      "evidence": [
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "数学上已经定义，不等于生产操作已经完成；复制完成，不等于所有消费者已经读完。"
        },
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "M、N、K 为非负整数；M=0 或 N=0 时没有输出工作，K=0 时输出为零。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "区分了数学覆盖、输出所有权、异步完成、可见性和最后读者条件，说明了矩阵指令的集体参与、布局和对齐要求，并将平台参数与性能选择限定到目标架构。",
      "evidence": [
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "消费者只在整槽复制完成并建立可见性后读取；槽只在全部读者结束后覆盖；旧代完成票据不得释放新代"
        },
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "全部 warp 线程以一致参数参加 load、mma 和 store；条件分支不得让部分线程跳过集体操作"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "正文已提供 SIMT 地址、线程所有权、共享布局、推进、排空和取消协议，也提供不依赖内部 fragment 映射的矩阵路径。但用于支持核心代次机制的旧票据负对照采用自报错误标签，未完成所声明的独立验证，见 K-HW-011-R1-002。",
      "evidence": [
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "等待两个warp都读完；此后槽s才可释放"
        },
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "旧代复制完成票据不得把新代槽发布为可读"
        }
      ]
    },
    "cost": {
      "assessment": "partial",
      "reason": "SIMT 工作量、CTA 重读、逻辑共享读取、驻留和完整调用边界基本连贯；地址算例独立复算一致。但 WMMA 输入共享容量多计一倍，直接影响该候选的资源账，见 K-HW-011-R1-001。",
      "evidence": [
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "共享输入 2 KiB、输出 1 KiB，尚未计对齐和同步对象。"
        },
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "copy 等待已在 kernel 关键路径里，就不能作为额外同步再次加上。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "说明了短归约、槽数、tile、dtype、架构、缓存工作集和取消变化时保留的依赖及需要重算的成本；容量反转案例明确保留驻留与共享通路假设，没有将理想时序冒充真实 kernel 性能。",
      "evidence": [
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "共享复制通路或带宽争用存在时，L/I/C 必须作为驻留数的函数重测，不能独立复制单 CTA 曲线。"
        },
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "没有合法高效路径就放弃"
        }
      ]
    },
    "diagnosis": {
      "assessment": "partial",
      "reason": "性能诊断具有竞争预测、受控干预和反证修正，也明确了混杂因素。但反向在线重标度被要求由凸包检查拒绝，而当前错误路径仍产生正权重的归一化平均，无法满足该判据；检查独立性另有缺口，见 K-HW-011-R1-002、003。",
      "evidence": [
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "反向重标度必须被凸包和独立参考拒绝"
        },
        {
          "path": "knowledge/hardware/gpu-kernel-pipelines.md",
          "quote": "三级的长 J 斜率更坏，不能再只归因首尾"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-HW-011-R1-001",
      "criterion": "cost",
      "evidence": "WMMA16 定义“共享 A_s[16,16]、B_s[16,16] 为 FP16，C_s[16,16] 为 FP32”，随后却写“共享输入 2 KiB、输出 1 KiB，尚未计对齐和同步对象。”",
      "impact": "两个 FP16 输入各为 16×16×2=512 字节，输入合计应为 1024 字节，即 1 KiB；独立输出暂存为 1 KiB，三者合计为 2 KiB。当前表述将输入容量多计一倍，会误导缓冲扩展与驻留估算，也与同段共享写入 1024 字节的账不一致。",
      "blocking": true,
      "required_revision": "将输入共享容量改为 1 KiB，明确输入与输出暂存合计 2 KiB；若有额外缓冲，逐对象说明其尺寸和同时存活条件。同步修正依赖该数值的账，并以对象尺寸求和核对。"
    },
    {
      "id": "K-HW-011-R1-002",
      "criterion": "algorithm",
      "evidence": "正文要求“脚本中的每个错误路径都应实际触发验证器，而不是只比较两个常数。”但脚本在 accept_stale 分支内自行执行 violations.append('stale-copy-accepted')，主检查仅要求 req('stale-copy-accepted' in run_slot_protocol(accept_stale=True), 'stale ticket must be detected')；用于检查状态未被旧票据改变的条件还带有“and not accept_stale”。WMMA 检查则仅为 req(16 % 8 == 0 and 16 % 4 == 0, 'WMMA leading dimensions') 与 req(15 % 8 != 0, 'WMMA negative leading dimension')。",
      "impact": "旧票据负对照的成功条件来自被注入分支自报标签：即使删除错误状态修改、只保留该标签，断言仍通过。它没有独立证明新代槽被错误发布。WMMA 的常数取模也未让非法参数进入同一个合法性判定路径。实际退出码 0 因此不足以支持这些机制检查已经成立。",
      "blocking": true,
      "required_revision": "将协议执行与独立状态观察分开：新代处于 FILLING 时投递旧票据，核对本代身份、copied、status 和读者状态保持不变，再确认本代真实票据仍能推进；删除身份防护的变体必须被同一观察器拒绝，不以变体自行添加的标签作为检测证据。WMMA leading dimension 应让合法与非法参数进入同一个参数化契约判定器，或明确撤回该常数检查的机制验证声称。重新执行并绑定修订脚本。"
    },
    {
      "id": "K-HW-011-R1-003",
      "criterion": "diagnosis",
      "evidence": "正文写“若把旧累加量向相反方向放大，会立即破坏该关系，甚至得到超出凸包的值”，并要求“反向重标度必须被凸包和独立参考拒绝”。脚本 reverse=True 同时使用反向系数更新 l 和 u，实际仅检查 abs(wrong - ref) > 0.05，没有凸包拒绝检查。",
      "impact": "给定 scores=[0,2]、vals=[1,0]，错误结果为 exp(2)/(exp(2)+1)≈0.880797，正确值约为 0.119203，两者都在 [0,1] 内。对分子和分母同时采用正的错误重标度，结果仍是某组正权重的归一化平均，因此凸包检查不能检测此类错误。当前文本提出了该负对照无法满足的反证条件。",
      "blocking": true,
      "required_revision": "明确当前反向重标度由独立整行参考或逐步 m/ℓ/U 不变量拒绝，不能依靠凸包拒绝；保留凸包作为必要但不充分条件，并用当前算例展示其漏检。若另举仅错误缩放 U 等会越出凸包的故障，应明确区分故障类型并实际检查。向共享来源说明的维护者报告相同误述，避免继续沿用。"
    }
  ],
  "limitations": [
    "没有目标 CUDA/HIP 编译、真实内存可见性、矩阵 fragment 内部映射、TMA 事务、spill、驻留、重叠或性能证据；正文对此已有清楚限定，属于可保留边界。",
    "CPU GEMM 使用 Python 浮点和小整数输入，不模拟完整 FP16/FP32 舍入、极端值或真实 attention 数值质量。",
    "所供 CUDA 原文摘录未覆盖完整 §7.24、§7.26–7.28、Feature Support 和 Table 24；相应结论部分依据完整来源说明，不能声称本次已逐项重读全部原始条款。",
    "未直接访问磁盘、重算所供文件哈希或检查相对链接存在性；documents 绑定采用任务提供的字面哈希。",
    "未重新执行 Python 脚本；实际运行结论来自所供 actual_preflight。独立复算仅在本次 functions.exec 的 JavaScript 中执行了 WMMA 字节数、三个地址偏移及两项 softmax 闭式值。",
    "没有 Agent 使用效果、真实模型质量、服务并发与设备取消路径验证；这些边界不作为新增验收条件。"
  ],
